import {auth,db,googleProvider,firebaseConfigured,authPersistence} from './firebase.js';
import {createUserWithEmailAndPassword,signInWithEmailAndPassword,signInWithPopup,signOut,onAuthStateChanged,updateProfile,sendPasswordResetEmail} from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-auth.js';
import {collection,doc,getDoc,getDocs,addDoc,setDoc,updateDoc,deleteDoc,query,where,orderBy,limit,serverTimestamp} from 'https://www.gstatic.com/firebasejs/12.0.0/firebase-firestore.js';
const $=id=>document.getElementById(id);const state={user:null,profile:null,isOwner:false,isStaff:false,staffRole:'',panel:'overview',orders:[],services:[],tickets:[],quotes:[],invoices:[],notifications:[],bookings:[],content:[],staff:[],users:[],settings:{},busy:false};
const DEFAULT_SERVICES=[{name:'Website Development',category:'Web',description:'Responsive business websites, landing pages and portfolios.',active:true},{name:'Web Applications',category:'Software',description:'Custom dashboards, portals and workflow tools.',active:true},{name:'E-commerce',category:'Commerce',description:'Online stores and commerce workflows.',active:true},{name:'Mobile App Development',category:'Mobile',description:'Mobile experiences and app development planning.',active:true},{name:'Bug Fixes & Improvements',category:'Support',description:'Resolve issues and improve existing software.',active:true},{name:'Maintenance & Support',category:'Support',description:'Ongoing technical support and maintenance.',active:true}];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=(n,c='PKR')=>{try{return new Intl.NumberFormat('en-PK',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(n)||0)}catch{return `${c} ${Number(n)||0}`}};const dt=v=>{try{const d=v?.toDate?v.toDate():v?new Date(v):null;return d&&!isNaN(d)?d.toLocaleDateString('en',{year:'numeric',month:'short',day:'numeric'}):'—'}catch{return '—'}};const stamp=()=>serverTimestamp();const fmt=s=>`<span class="pill ${['completed','paid','approved','answered','confirmed'].includes(s)?'green':['cancelled','rejected','failed','overdue'].includes(s)?'red':['pending','open','quoted','partial','requested'].includes(s)?'orange':''}">${esc(String(s||'pending').replaceAll('_',' '))}</span>`;const btn=(label,action,kind='mini-btn')=>`<button type="button" class="${kind}" data-action="${esc(action)}">${esc(label)}</button>`;const empty=(title,desc)=>`<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;function toast(s,error=false){const el=$('toast');el.textContent=s;el.classList.remove('hidden','error');if(error)el.classList.add('error');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),4200)}function msg(id,s,error=false){const el=$(id);if(!el)return;el.textContent=s;el.classList.toggle('error',error)}function errText(e){const c=e?.code||'';if(c.includes('permission-denied'))return 'Permission denied. Check Firestore Rules and owner access setup.';if(c.includes('auth/email-already-in-use'))return 'This email already has an account. Please log in.';if(c.includes('auth/invalid-credential'))return 'Email or password is incorrect.';if(c.includes('auth/weak-password'))return 'Use a password with at least 6 characters.';if(c.includes('auth/unauthorized-domain'))return 'Add this domain to Firebase Authentication authorized domains.';if(c.includes('auth/popup-closed-by-user'))return 'Google sign-in was cancelled.';return e?.message||'Something went wrong. Please try again.'}function showModal(id){$(id).classList.remove('hidden');document.body.classList.add('modal-open')}function closeModal(id){$(id).classList.add('hidden');if(!document.querySelector('.modal:not(.hidden)'))document.body.classList.remove('modal-open')}function authModal(mode='login'){setAuthMode(mode);showModal('authModal')}function setAuthMode(mode){let signup=mode==='signup';$('tabLogin').classList.toggle('active',!signup);$('tabSignup').classList.toggle('active',signup);$('authTitle').textContent=signup?'Create your account':'Welcome back';$('authSubtitle').textContent=signup?'Create an account to track projects and invoices.':'Sign in to your Brightora workspace.';$('nameLabel').classList.toggle('hidden',!signup);$('authName').required=signup;$('authPassword').autocomplete=signup?'new-password':'current-password';$('authSubmit').textContent=signup?'Create account':'Log in';$('resetPassword').classList.toggle('hidden',signup);msg('authMessage','')}
function openProject(service=''){if(!state.user){authModal('login');toast('Please sign in before submitting a project request.');return}$('projectService').value=service||'Website Development';msg('projectMessage','');showModal('projectModal')}
async function readOwnerAccess(uid){try{const s=await getDoc(doc(db,'settings','ownerAccess'));const d=s.exists()?s.data():{};state.isOwner=Array.isArray(d.ownerUids)&&d.ownerUids.includes(uid);state.isStaff=Array.isArray(d.staffUids)&&d.staffUids.includes(uid);state.staffRole=d.staffRoles?.[uid]||'staff'}catch(e){state.isOwner=false;state.isStaff=false;console.warn('Owner access lookup failed',e)}}
async function ensureProfile(user,name=''){const r=doc(db,'users',user.uid);const s=await getDoc(r);if(!s.exists())await setDoc(r,{uid:user.uid,name:name||user.displayName||'',email:user.email||'',phone:'',city:'',country:'Pakistan',createdAt:stamp(),updatedAt:stamp()});const latest=await getDoc(r);state.profile=latest.data()||{};await readOwnerAccess(user.uid)}
async function getRows(name,limitN=150,sortField='updatedAt'){try{let q=query(collection(db,name),limit(limitN));if(sortField)q=query(collection(db,name),orderBy(sortField,'desc'),limit(limitN));const s=await getDocs(q);return s.docs.map(d=>({id:d.id,...d.data()}))}catch(e){try{const s=await getDocs(query(collection(db,name),limit(limitN)));return s.docs.map(d=>({id:d.id,...d.data()}))}catch{return []}}}
async function loadPublic(){try{const ss=await getDocs(query(collection(db,'services'),where('active','==',true),limit(100)));state.services=ss.docs.map(d=>({id:d.id,...d.data()}))}catch{state.services=[]}if(!state.services.length)state.services=DEFAULT_SERVICES;try{const cs=await getDocs(query(collection(db,'siteContent'),where('published','==',true),limit(100)));state.content=cs.docs.map(d=>({id:d.id,...d.data()}))}catch{state.content=[]}renderPublicDynamic();try{const s=await getDoc(doc(db,'settings','public'));if(s.exists()){state.settings=s.data();const brand=state.settings.brandName||'Brightora Technologies';$('footerBrand').textContent=brand;$('footerEmail').href=state.settings.supportEmail?'mailto:'+state.settings.supportEmail:'#contact';if(state.settings.supportEmail)$('footerEmail').textContent=state.settings.supportEmail}}catch{}}
function renderPublicDynamic(){const sg=$('serviceGrid');if(sg&&state.services.filter(s=>s.active===true).length)sg.innerHTML=state.services.filter(s=>s.active===true).map(s=>`<article class="service-card"><span class="service-icon">✦</span><h3>${esc(s.name)}</h3><p>${esc(s.description||'A digital solution tailored to your needs.')}</p><div class="service-meta"><span>${esc(s.category||'Development')}</span><span>${s.startingPrice?esc(money(s.startingPrice,s.currency||'PKR')):'Custom quote'}</span></div><button class="text-link" data-service="${esc(s.name)}">Discuss this service ↗</button></article>`).join('');const portfolio=state.content.filter(c=>c.type==='portfolio'&&c.published===true);if(portfolio.length)$('portfolioGrid').innerHTML=portfolio.map(c=>`<article class="portfolio-card"><div class="portfolio-art art1">✦</div><h3>${esc(c.title)}</h3><span>${esc(c.category||'Selected work')}</span><p style="padding:0 20px;font-size:12px;color:#9ba8c2">${esc(c.body||'')}</p>${c.url?`<a class="text-link" style="margin:0 20px" href="${esc(safeUrl(c.url))}" target="_blank" rel="noopener">View project ↗</a>`:''}</article>`).join('')}
function safeUrl(s){try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function signedUI(user){const signed=!!user;$('loginNav').classList.toggle('hidden',signed);$('startNav').classList.toggle('hidden',signed);$('dashboardNav').classList.toggle('hidden',!signed);$('accountNav').classList.toggle('hidden',!signed);$('accountNav').textContent=(user?.displayName||user?.email||'A').charAt(0).toUpperCase();$('userInitial').textContent=(user?.displayName||user?.email||'A').charAt(0).toUpperCase();$('workspaceName').textContent=state.profile?.name||user?.displayName||'Your workspace';$('workspaceEmail').textContent=user?.email||''}
function portalNav(){const base=[['overview','◫','Overview'],['projects','▣','Projects'],['quotes','＄','Quotes'],['invoices','▤','Invoices'],['bookings','◷','Bookings'],['notifications','♢','Notifications'],['support','✉','Support'],['profile','◎','My profile']];const admin=[['admin-dashboard','▦','Admin dashboard'],['admin-projects','▣','Manage projects'],['admin-quotes','＄','Manage quotes'],['admin-invoices','▤','Manage invoices'],['admin-bookings','◷','Manage bookings'],['admin-support','✉','Support inbox'],['admin-cms','▤','Website CMS'],['admin-services','⌘','Services'],['admin-staff','♙','Staff & access'],['admin-reports','▥','Reports'],['admin-audit','≋','Activity log'],['admin-settings','⚙','Settings']];const nav=[...base,...(state.isOwner?admin:state.isStaff?admin.filter(x=>['admin-dashboard','admin-projects','admin-quotes','admin-invoices','admin-bookings','admin-support'].includes(x[0])):[])];$('portalNav').innerHTML=nav.map(([id,icon,label])=>`<button class="${state.panel===id?'active':''}" data-panel="${id}"><span>${icon}</span>${label}</button>`).join('')}
function head(title,sub=''){return `<div class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div></div>`}function stat(label,value,small=''){return `<div class="stat-card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(small)}</small></div>`}function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">No records yet.</td></tr>`}</tbody></table></div>`}
async function clientRows(name,field='clientUid'){try{const s=await getDocs(query(collection(db,name),where(field,'==',state.user.uid),limit(200)));return s.docs.map(d=>({id:d.id,...d.data()}))}catch{return []}}
async function refreshData(){const privileged=state.isOwner||state.isStaff;state.orders=privileged?await getRows('orders',200,'createdAt'):await clientRows('orders');state.tickets=privileged?await getRows('supportTickets',100,'createdAt'):await clientRows('supportTickets');state.quotes=privileged?await getRows('quotes',150,'createdAt'):await clientRows('quotes');state.invoices=privileged?await getRows('invoices',150,'createdAt'):await clientRows('invoices');state.bookings=privileged?await getRows('bookings',100,'createdAt'):await clientRows('bookings');state.notifications=privileged?await getRows('notifications',100,'createdAt'):await clientRows('notifications','uid');if(privileged){state.users=state.isOwner||state.isStaff?await getRows('users',300,'createdAt'):[];state.staff=state.isOwner?await getRows('staff',100,'createdAt'):[];state.content=await getRows('siteContent',100,'updatedAt');state.services=await getRows('services',100,'createdAt');state.inquiries=state.isOwner||state.isStaff?await getRows('inquiries',100,'createdAt'):[]}}
function clientOverview(){let own=state.orders.filter(o=>o.clientUid===state.user.uid);let qs=state.quotes.filter(q=>q.clientUid===state.user.uid);let inv=state.invoices.filter(i=>i.clientUid===state.user.uid);let open=state.tickets.filter(t=>t.clientUid===state.user.uid&&t.status!=='closed');return `<div class="stat-grid">${stat('My projects',own.length)}${stat('Quotes received',qs.length)}${stat('Invoices',inv.length)}${stat('Open support',open.length)}</div><div class="panel-card">${head('Recent projects','Project updates are shown here after your request is reviewed.')}${own.length?table(['Project','Status','Updated'],own.slice(0,6).map(o=>`<tr><td>${esc(o.title)}</td><td>${fmt(o.status)}</td><td>${dt(o.updatedAt||o.createdAt)}</td></tr>`).join('')):empty('No projects yet','Start a project request to begin working with Brightora.')}</div><div class="panel-card">${head('Quick actions')}<button class="btn primary" data-action="new-project">＋ Request a project</button> <button class="btn ghost" data-panel="booking-new">Book a consultation</button></div>`}
function renderProjects(admin=false){let rows=admin?state.orders:state.orders.filter(o=>o.clientUid===state.user.uid);return `<div class="panel-card">${head(admin?'All project requests':'Your projects','Use project status and progress to follow each engagement.')}<div class="filter-row"><input id="projectSearch" placeholder="Search projects…"><select id="projectFilter"><option value="">All statuses</option>${['pending','quoted','approved','in_progress','review','completed','cancelled','rejected'].map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></div>${table(['Project / client','Service','Status','Quote','Updated','Actions'],rows.map(o=>`<tr><td><b>${esc(o.title)}</b><br><small>${esc(o.clientName||o.clientEmail||'')}</small></td><td>${esc(o.service)}</td><td>${fmt(o.status)}</td><td>${o.quoteAmount==null?'Pending':money(o.quoteAmount,o.currency||'PKR')}</td><td>${dt(o.updatedAt||o.createdAt)}</td><td>${admin?btn('Update','edit-project:'+o.id):btn('Details','view-project:'+o.id)}</td></tr>`).join(''))}</div>`}
function renderQuotes(admin=false){let rows=admin?state.quotes:state.quotes.filter(q=>q.clientUid===state.user.uid);return `<div class="panel-card">${head(admin?'Quotation management':'Your quotations','Quotes are proposals and become approved only after client acceptance.')} ${admin?`<button class="btn primary" data-action="new-quote">＋ Create quote</button>`:''}${table(['Reference','Project','Amount','Status','Valid until','Actions'],rows.map(q=>`<tr><td>${esc(q.number||q.id.slice(0,8))}</td><td>${esc(q.projectTitle||q.orderTitle||'Project')}</td><td>${money(q.total||q.amount||0,q.currency||'PKR')}</td><td>${fmt(q.status)}</td><td>${dt(q.validUntil)}</td><td>${admin?btn('Edit status','quote-status:'+q.id):q.status==='sent'?btn('Accept quote','accept-quote:'+q.id):'—'} ${btn('View','view-quote:'+q.id)}</td></tr>`).join(''))}</div>`}
function renderInvoices(admin=false){let rows=admin?state.invoices:state.invoices.filter(i=>i.clientUid===state.user.uid);return `<div class="panel-card">${head(admin?'Invoice management':'Invoices & payments','Payment status is only updated after verified payment or an authorized manual record.')} ${admin?`<button class="btn primary" data-action="new-invoice">＋ Create invoice</button>`:''}${table(['Invoice','Project','Total','Paid','Status','Due','Actions'],rows.map(i=>`<tr><td>${esc(i.number||i.id.slice(0,8))}</td><td>${esc(i.projectTitle||'Project')}</td><td>${money(i.total||0,i.currency||'PKR')}</td><td>${money(i.amountPaid||0,i.currency||'PKR')}</td><td>${fmt(i.status)}</td><td>${dt(i.dueDate)}</td><td>${btn('Print','print-invoice:'+i.id)} ${admin?btn('Record payment','record-payment:'+i.id):btn('Payment options','pay-invoice:'+i.id)}</td></tr>`).join(''))}<p class="muted">Online payment requires a merchant account and server-side gateway credentials. Until configured, invoices remain payable using the instructions provided by the business.</p></div>`}
function renderBookings(admin=false){let rows=admin?state.bookings:state.bookings.filter(b=>b.clientUid===state.user.uid);return `<div class="panel-card">${head(admin?'Consultation bookings':'Book a consultation','Choose a time for a discovery call. Confirmation is subject to availability.')} ${!admin?`<button class="btn primary" data-action="new-booking">＋ Request a booking</button>`:''}${table(['Date & time','Topic','Client','Status','Actions'],rows.map(b=>`<tr><td>${esc(b.date||'')} ${esc(b.time||'')}</td><td>${esc(b.topic||'Consultation')}</td><td>${esc(b.clientEmail||'')}</td><td>${fmt(b.status)}</td><td>${admin?btn('Update status','booking-status:'+b.id):'—'}</td></tr>`).join(''))}</div>`}
function renderSupport(admin=false){let rows=admin?state.tickets:state.tickets.filter(t=>t.clientUid===state.user.uid);return `<div class="panel-card">${head(admin?'Support inbox':'Support center','Keep project communication in your account rather than public phone details.')} ${!admin?`<form id="supportForm" class="dashboard-form"><label>Subject<input name="subject" required minlength="3" maxlength="120"></label><label>Related project<input name="orderId" placeholder="Optional project ID"></label><label class="span-2">Message<textarea name="message" rows="3" required minlength="10" maxlength="3000"></textarea></label><button class="btn primary" type="submit">Send support request</button><p class="form-message" id="supportMessage"></p></form>`:''}<div class="data-list">${rows.map(t=>`<article class="data-card"><div><h3>${esc(t.subject)}</h3><p>${esc(t.message)}</p><small class="muted">${esc(t.clientEmail||'')} · ${dt(t.createdAt)}</small>${t.adminReply?`<div class="notice success"><b>Reply:</b> ${esc(t.adminReply)}</div>`:''}</div><div>${fmt(t.status)}<div class="actions">${admin?btn('Reply','reply-ticket:'+t.id):''}${admin?btn('Close','close-ticket:'+t.id):''}</div></div></article>`).join('')||empty('No support requests','Messages will appear here.')}</div>${admin?`<div class="panel-card">${head('Website inquiries','Messages sent from the public contact form.')}${table(['Name','Email','Message','Date'],(state.inquiries||[]).map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.email)}</td><td>${esc(i.message)}</td><td>${dt(i.createdAt)}</td></tr>`).join(''))}</div>`:''}</div>`}
function renderProfile(){let p=state.profile||{};return `<div class="panel-card">${head('My profile','Your contact details are only available to authorized accounts.')}<form id="profileForm" class="dashboard-form"><label>Full name<input name="name" required minlength="2" maxlength="100" value="${esc(p.name||state.user.displayName||'')}"></label><label>Email<input value="${esc(state.user.email||'')}" disabled></label><label>Phone<input name="phone" maxlength="40" value="${esc(p.phone||'')}"></label><label>City<input name="city" maxlength="100" value="${esc(p.city||'')}"></label><label>Country<input name="country" maxlength="100" value="${esc(p.country||'Pakistan')}"></label><label class="span-2">Project notes<textarea name="notes" maxlength="1000" rows="3">${esc(p.notes||'')}</textarea></label><button class="btn primary" type="submit">Save profile</button><p id="profileMessage" class="form-message"></p></form></div>`}
function renderNotifications(){let rows=state.notifications.filter(n=>n.uid===state.user.uid||state.isOwner);return `<div class="panel-card">${head('Notifications','Project, quote, invoice and booking updates.')}<div class="data-list">${rows.map(n=>`<article class="data-card"><div><h3>${esc(n.title||'Update')}</h3><p>${esc(n.message||'')}</p><small class="muted">${dt(n.createdAt)}</small></div>${fmt(n.read?'read':'unread')}</article>`).join('')||empty('You are all caught up','New updates will appear here.')}</div></div>`}
function adminDashboard(){let pending=state.orders.filter(o=>o.status==='pending').length,active=state.orders.filter(o=>['approved','in_progress','review'].includes(o.status)).length,unpaid=state.invoices.filter(i=>!['paid','cancelled'].includes(i.status)).reduce((a,i)=>a+Math.max(0,Number(i.total||0)-Number(i.amountPaid||0)),0),revenue=state.invoices.reduce((a,i)=>a+Number(i.amountPaid||0),0);let statuses=['pending','quoted','approved','in_progress','review','completed'];return `<div class="stat-grid">${stat('Clients',state.users.length)}${stat('Projects',state.orders.length)}${stat('Active projects',active)}${stat('Pending requests',pending)}${stat('Recorded revenue',money(revenue,'PKR'))}${stat('Outstanding balance',money(unpaid,'PKR'))}${stat('Open tickets',state.tickets.filter(t=>t.status!=='closed').length)}${stat('Bookings',state.bookings.length)}</div><div class="panel-card">${head('Project status overview','Counts reflect current Firestore records.')}<div class="chart-bars">${statuses.map(s=>{let n=state.orders.filter(o=>o.status===s).length;let h=Math.max(5,Math.min(100,n/Math.max(1,state.orders.length)*100));return `<div class="chart-bar" style="height:${h}%" title="${esc(s)}: ${n}"><small>${esc(s.replace('_',' '))}</small></div>`}).join('')}</div></div><div class="panel-card">${head('Recent requests')}${table(['Project','Client','Status','Date'],state.orders.slice(0,8).map(o=>`<tr><td>${esc(o.title)}</td><td>${esc(o.clientEmail||'')}</td><td>${fmt(o.status)}</td><td>${dt(o.createdAt)}</td></tr>`).join(''))}</div>`}
function renderCMS(){return `<div class="panel-card">${head('Website content manager','Published items appear on the public website when their type is supported.')}<form id="cmsForm" class="dashboard-form"><label>Content type<select name="type"><option value="portfolio">Portfolio project</option><option value="testimonial">Testimonial</option><option value="faq">FAQ</option><option value="pricing">Pricing package</option></select></label><label>Title<input name="title" required maxlength="140"></label><label>Category / label<input name="category" maxlength="100"></label><label>External URL<input name="url" type="url" placeholder="https://..."></label><label class="span-2">Description / body<textarea name="body" rows="3" maxlength="2500"></textarea></label><label><span><input type="checkbox" name="published" checked style="width:auto"> Published</span></label><button class="btn primary" type="submit">Add content</button></form></div><div class="panel-card">${head('Existing content')}${table(['Type','Title','Published','Actions'],state.content.map(c=>`<tr><td>${esc(c.type)}</td><td>${esc(c.title)}</td><td>${fmt(c.published?'published':'draft')}</td><td>${btn(c.published?'Unpublish':'Publish','toggle-content:'+c.id)} ${btn('Delete','delete-content:'+c.id,'mini-btn danger')}</td></tr>`).join(''))}</div>`}
function renderServicesAdmin(){return `<div class="panel-card">${head('Service catalogue','Manage the public services list.')}<form id="serviceForm" class="dashboard-form"><label>Service name<input name="name" required maxlength="100"></label><label>Category<input name="category" required maxlength="60"></label><label>Starting price (optional)<input name="startingPrice" type="number" min="0" step="0.01"></label><label>Currency<select name="currency"><option>PKR</option><option>USD</option></select></label><label class="span-2">Description<textarea name="description" required minlength="10" maxlength="1000"></textarea></label><label><span><input type="checkbox" name="active" checked style="width:auto"> Publicly visible</span></label><button class="btn primary" type="submit">Add service</button></form></div><div class="panel-card">${table(['Service','Category','Status','Actions'],state.services.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.category)}</td><td>${fmt(s.active?'active':'hidden')}</td><td>${btn(s.active?'Hide':'Publish','toggle-service:'+s.id)} ${btn('Delete','delete-service:'+s.id,'mini-btn danger')}</td></tr>`).join(''))}</div>`}
function renderStaff(){return `<div class="panel-card">${head('Staff access','Add an existing Firebase Authentication UID. Staff permissions are constrained by Firestore Rules.')}<form id="staffForm" class="dashboard-form"><label>Staff member UID<input name="uid" required minlength="10" maxlength="128"></label><label>Display name<input name="name" required maxlength="100"></label><label>Role<select name="role"><option value="project_manager">Project manager</option><option value="support">Support</option><option value="finance">Finance</option><option value="staff">General staff</option></select></label><button class="btn primary" type="submit">Add staff access</button></form><div class="notice warning">After adding staff here, the same UID must also be added to <code>settings/ownerAccess.staffUids</code> and the role map. This prevents the UI alone from granting privileges.</div></div><div class="panel-card">${table(['Name','UID','Role','Status'],state.staff.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.uid)}</td><td>${esc(s.role)}</td><td>${fmt(s.active===false?'disabled':'active')} ${btn('Disable','disable-staff:'+s.id)}</td></tr>`).join(''))}</div>`}
function renderSettings(){let s=state.settings||{};return `<div class="panel-card">${head('Store and company settings','Public settings may be read by visitors; private gateway secrets must never be stored here.')}<form id="settingsForm" class="dashboard-form"><label>Company name<input name="brandName" required maxlength="100" value="${esc(s.brandName||'Brightora Technologies')}"></label><label>Support email<input name="supportEmail" type="email" maxlength="160" value="${esc(s.supportEmail||'')}"></label><label>Default currency<select name="currency"><option ${(!s.currency||s.currency==='PKR')?'selected':''}>PKR</option><option ${s.currency==='USD'?'selected':''}>USD</option></select></label><label>Consultation duration (minutes)<input name="bookingDuration" type="number" min="15" max="180" value="${esc(s.bookingDuration||30)}"></label><label class="span-2">Manual payment instructions<textarea name="paymentInstructions" rows="3" maxlength="2000">${esc(s.paymentInstructions||'')}</textarea></label><label><span><input type="checkbox" name="maintenanceMode" ${s.maintenanceMode?'checked':''} style="width:auto"> Maintenance mode (notice only)</span></label><button class="btn primary" type="submit">Save settings</button></form><p class="muted">Online gateway status: not connected until a supported merchant account, credentials and verified server webhook are configured.</p></div>`}
function renderReports(){let rows=state.orders;let csv='Project,Client,Status,Currency,Quote,Created\n'+rows.map(o=>[o.title,o.clientEmail,o.status,o.currency,o.quoteAmount,dt(o.createdAt)].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');return `<div class="panel-card">${head('Reports & exports','Export current project records. Revenue reflects recorded invoice payments, not bank reconciliation.')}<button class="btn primary" data-action="download-csv">Download projects CSV</button> <button class="btn ghost" data-action="download-invoices">Download invoices CSV</button><div class="stat-grid" style="margin-top:20px">${stat('Projects',state.orders.length)}${stat('Quotes',state.quotes.length)}${stat('Invoices',state.invoices.length)}${stat('Recorded payments',money(state.invoices.reduce((a,i)=>a+Number(i.amountPaid||0),0),'PKR'))}</div></div>`}
function renderAudit(){return `<div class="panel-card">${head('Audit trail','Append-only activity events. For compliance-sensitive actions, use trusted server-side logging.')} ${table(['Action','Actor','Target','Time','Details'],state.audit.map(a=>`<tr><td>${esc(a.action)}</td><td>${esc(a.actorEmail||a.actorUid||'')}</td><td>${esc(a.targetType||'')} ${esc(a.targetId||'')}</td><td>${dt(a.createdAt)}</td><td>${esc(a.details||'')}</td></tr>`).join(''))}</div>`}
async function renderPortal(){if(!state.user)return;state.portalBusy=true;portalNav();$('portal').classList.remove('hidden');$('publicSite').classList.add('hidden');document.querySelector('.footer').classList.add('hidden');$('portalTitle').textContent=({overview:'Overview',projects:'Projects',quotes:'Quotes',invoices:'Invoices',bookings:'Bookings',notifications:'Notifications',support:'Support center',profile:'My profile','admin-dashboard':'Admin dashboard','admin-projects':'Manage projects','admin-quotes':'Manage quotes','admin-invoices':'Manage invoices','admin-bookings':'Manage bookings','admin-support':'Support inbox','admin-cms':'Website CMS','admin-services':'Services','admin-staff':'Staff & access','admin-reports':'Reports','admin-audit':'Activity log','admin-settings':'Settings','booking-new':'Book a consultation'}[state.panel]||'Workspace');$('portalEyebrow').textContent=state.isOwner?'OWNER CONTROL PANEL':state.isStaff?'STAFF WORKSPACE':'CLIENT WORKSPACE';$('newProjectButton').classList.toggle('hidden',state.panel.startsWith('admin-'));$('portalContent').innerHTML='<div class="loading">Loading records…</div>';await refreshData();if(state.panel==='admin-audit')state.audit=await getRows('activityLogs',200,'createdAt');let html='';switch(state.panel){case'overview':html=state.isOwner||state.isStaff?adminDashboard():clientOverview();break;case'projects':html=renderProjects(false);break;case'quotes':html=renderQuotes(false);break;case'invoices':html=renderInvoices(false);break;case'bookings':html=renderBookings(false);break;case'notifications':html=renderNotifications();break;case'support':html=renderSupport(false);break;case'profile':html=renderProfile();break;case'admin-dashboard':html=adminDashboard();break;case'admin-projects':html=renderProjects(true);break;case'admin-quotes':html=renderQuotes(true);break;case'admin-invoices':html=renderInvoices(true);break;case'admin-bookings':html=renderBookings(true);break;case'admin-support':html=renderSupport(true);break;case'admin-cms':html=renderCMS();break;case'admin-services':html=renderServicesAdmin();break;case'admin-staff':html=renderStaff();break;case'admin-reports':html=renderReports();break;case'admin-audit':html=renderAudit();break;case'admin-settings':html=renderSettings();break;case'booking-new':html=`<div class="panel-card">${head('Request a consultation')}<form id="bookingForm" class="dashboard-form"><label>Date<input name="date" type="date" required min="${new Date().toISOString().slice(0,10)}"></label><label>Preferred time<input name="time" type="time" required></label><label>Topic<input name="topic" required minlength="3" maxlength="150"></label><label>Timezone<input name="timezone" value="Asia/Karachi" required></label><button class="btn primary" type="submit">Request booking</button><p id="bookingMessage" class="form-message"></p></form></div>`;break;default:html=clientOverview()}$('portalContent').innerHTML=html;state.portalBusy=false}
async function audit(action,targetType,targetId,details=''){try{await addDoc(collection(db,'activityLogs'),{action,actorUid:state.user?.uid||'',actorEmail:state.user?.email||'',targetType,targetId,details:String(details).slice(0,500),createdAt:stamp()})}catch(e){console.warn('Audit log write unavailable',e)}}async function notify(uid,title,message){try{await addDoc(collection(db,'notifications'),{uid,title,message,read:false,createdAt:stamp()})}catch(e){console.warn('Notification write failed',e)}}
async function handleAuth(e){e.preventDefault();if(!firebaseConfigured){msg('authMessage','Add the Web API key and App ID in js/firebase.js first.',true);return}if(state.busy)return;state.busy=true;$('authSubmit').disabled=true;try{await authPersistence;let email=$('authEmail').value.trim(),password=$('authPassword').value,signup=$('tabSignup').classList.contains('active'),name=$('authName').value.trim();if(signup){if(name.length<2)throw Error('Please enter your full name.');let c=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(c.user,{displayName:name});await ensureProfile(c.user,name)}else await signInWithEmailAndPassword(auth,email,password);closeModal('authModal');$('authForm').reset();toast(signup?'Account created.':'Signed in successfully.')}catch(e){msg('authMessage',errText(e),true)}finally{state.busy=false;$('authSubmit').disabled=false}}
async function submitProject(e){e.preventDefault();if(!state.user){authModal();return}let f=e.currentTarget,fd=new FormData(f),requirements=String(fd.get('requirements')||'').trim(),url=String(fd.get('referenceUrl')||'').trim();if(requirements.length<20){msg('projectMessage','Please provide at least 20 characters of requirements.',true);return}if(url&&!safeUrl(url)){msg('projectMessage','Please enter a valid HTTP/HTTPS URL.',true);return}let b=$('projectSubmit');b.disabled=true;try{let ref=await addDoc(collection(db,'orders'),{clientUid:state.user.uid,clientName:state.profile?.name||state.user.displayName||'',clientEmail:state.user.email||'',service:String(fd.get('service')),title:String(fd.get('title')).trim(),requirements,budget:String(fd.get('budget')||''),deadline:String(fd.get('deadline')||''),referenceUrl:url,status:'pending',currency:'PKR',quoteAmount:null,adminNote:'',paymentStatus:'unpaid',amountPaid:0,progress:0,createdAt:stamp(),updatedAt:stamp()});await audit('project.requested','orders',ref.id,'New project request');await notifyOwner('New project request',`${state.user.email} submitted ${String(fd.get('title'))}.`);f.reset();closeModal('projectModal');state.panel='projects';await renderPortal();toast('Project request submitted.')}catch(e){msg('projectMessage',errText(e),true)}finally{b.disabled=false}}
async function notifyOwner(title,message){try{let a=await getDoc(doc(db,'settings','ownerAccess'));let uids=a.exists()&&Array.isArray(a.data().ownerUids)?a.data().ownerUids:[];for(const uid of uids)await notify(uid,title,message)}catch{}}
async function handleContact(e){e.preventDefault();let fd=new FormData(e.currentTarget);try{await addDoc(collection(db,'inquiries'),{name:String(fd.get('name')).trim(),email:String(fd.get('email')).trim(),message:String(fd.get('message')).trim(),status:'new',createdAt:stamp()});e.currentTarget.reset();msg('contactMessage','Thank you. Your inquiry has been received.')}catch(e){msg('contactMessage','Unable to submit right now. Please try again later.',true)}}
async function makeQuote(){if(!state.isOwner&&!state.isStaff)return;let orderId=prompt('Enter project document ID (from Manage projects):');if(!orderId)return;let o=state.orders.find(x=>x.id===orderId);if(!o){toast('Project not found in loaded records. Open Manage projects and copy its ID.',true);return}let amount=Number(prompt('Quote total amount in PKR'));if(!Number.isFinite(amount)||amount<=0){toast('Enter a positive quote amount.',true);return}let note=prompt('Scope / quote notes (optional)')||'';let ref=await addDoc(collection(db,'quotes'),{clientUid:o.clientUid,clientEmail:o.clientEmail||'',orderId:o.id,projectTitle:o.title,amount,total:amount,currency:'PKR',notes:note,status:'sent',validUntil:'',createdAt:stamp(),updatedAt:stamp(),createdBy:state.user.uid});await updateDoc(doc(db,'orders',o.id),{status:'quoted',quoteAmount:amount,updatedAt:stamp()});await notify(o.clientUid,'New quotation',`A quotation for ${o.title} is ready to review.`);await audit('quote.created','quotes',ref.id,`Quote created for ${o.title}`);toast('Quote created and client notified.');state.panel='admin-quotes';await renderPortal()}
async function makeInvoice(){let orderId=prompt('Enter project document ID:');if(!orderId)return;let o=state.orders.find(x=>x.id===orderId);if(!o){toast('Project not found. Open Manage projects and copy its ID.',true);return}let amount=Number(prompt('Invoice total amount (PKR)',String(o.quoteAmount||0)));if(!Number.isFinite(amount)||amount<=0){toast('Enter a positive invoice amount.',true);return}let due=prompt('Due date (YYYY-MM-DD, optional)','');let ref=await addDoc(collection(db,'invoices'),{clientUid:o.clientUid,clientEmail:o.clientEmail||'',orderId:o.id,projectTitle:o.title,number:'AC-'+Date.now().toString().slice(-8),items:[{description:o.title,quantity:1,unitPrice:amount}],subtotal:amount,tax:0,total:amount,currency:'PKR',amountPaid:0,status:'unpaid',dueDate:due||'',createdAt:stamp(),updatedAt:stamp(),createdBy:state.user.uid});await notify(o.clientUid,'New invoice',`Invoice ${ref.id.slice(0,8)} has been issued.`);await audit('invoice.created','invoices',ref.id,`Invoice issued for ${o.title}`);toast('Invoice created.');state.panel='admin-invoices';await renderPortal()}
async function action(action){let [v,id]=action.split(':');if(v==='new-project'){openProject();return}if(v==='new-booking'){state.panel='booking-new';await renderPortal();return}if(v==='new-quote'){await makeQuote();return}if(v==='new-invoice'){await makeInvoice();return}if(v==='download-csv'||v==='download-invoices'){let rows=v==='download-csv'?state.orders:state.invoices;let keys=v==='download-csv'?['id','title','clientEmail','status','currency','quoteAmount','createdAt']:['id','number','clientEmail','projectTitle','total','amountPaid','status','dueDate'];let csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(k==='createdAt'||k==='dueDate'?dt(r[k]):r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=v==='download-csv'?'brightora-projects.csv':'brightora-invoices.csv';a.click();URL.revokeObjectURL(a.href);return}if(v==='view-project'){let o=state.orders.find(x=>x.id===id);if(o)alert(`Project: ${o.title}\nStatus: ${o.status}\nProgress: ${o.progress||0}%\nUpdate: ${o.adminNote||'No update'}\n\nRequirements:\n${o.requirements}`);return}if(v==='view-quote'){let q=state.quotes.find(x=>x.id===id);if(q)alert(`Quotation ${q.number||q.id}\nProject: ${q.projectTitle}\nAmount: ${money(q.total||q.amount,q.currency)}\nStatus: ${q.status}\nNotes: ${q.notes||''}`);return}if(v==='accept-quote'){let q=state.quotes.find(x=>x.id===id);if(!q||q.clientUid!==state.user.uid||q.status!=='sent'){toast('This quote cannot be accepted.',true);return}if(!confirm('Accept this quotation?'))return;await updateDoc(doc(db,'quotes',id),{status:'accepted',acceptedAt:stamp(),updatedAt:stamp()});await updateDoc(doc(db,'orders',q.orderId),{status:'approved',updatedAt:stamp()});await notifyOwner('Quotation accepted',`${state.user.email} accepted quote ${id}.`);await audit('quote.accepted','quotes',id,'Client accepted quote');toast('Quote accepted.');await renderPortal();return}if(v==='print-invoice'){let i=state.invoices.find(x=>x.id===id);if(!i||(!state.isOwner&&i.clientUid!==state.user.uid))return;let w=window.open('','_blank');if(!w){toast('Allow popups to print the invoice.',true);return}w.document.write(`<html><head><title>Invoice ${esc(i.number||i.id)}</title><style>body{font:15px Arial;max-width:800px;margin:40px auto;color:#182238}h1{font-size:32px}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><h1>Brightora Technologies</h1><h2>INVOICE ${esc(i.number||i.id)}</h2><p>Client: ${esc(i.clientEmail||'')}<br>Project: ${esc(i.projectTitle||'')}<br>Due: ${esc(i.dueDate||'—')}</p><table><tr><th>Description</th><th>Amount</th></tr>${(i.items||[{description:i.projectTitle||'Services',unitPrice:i.total}]).map(x=>`<tr><td>${esc(x.description)}</td><td>${esc(money(x.unitPrice,i.currency))}</td></tr>`).join('')}<tr><th>Total</th><th>${esc(money(i.total,i.currency))}</th></tr><tr><td>Paid</td><td>${esc(money(i.amountPaid,i.currency))}</td></tr></table><p>Status: ${esc(i.status)}</p><p>Payment instructions: ${esc(state.settings.paymentInstructions||'Contact support for payment instructions.')}</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();return}if(v==='pay-invoice'){toast(state.settings.paymentInstructions||'Online payment is not configured yet. Contact the company using the support form.');return}if(v==='new-booking'){state.panel='booking-new';await renderPortal();return}
const ownerActions=['edit-project','quote-status','record-payment','booking-status','reply-ticket','close-ticket','toggle-content','delete-content','toggle-service','delete-service','disable-staff'];if(ownerActions.includes(v)&&!state.isOwner&&!state.isStaff){toast('Administrator permission required.',true);return}
if(v==='edit-project'){let o=state.orders.find(x=>x.id===id);if(!o)return;let status=prompt('Status: pending, quoted, approved, in_progress, review, completed, cancelled, rejected',o.status);if(!status)return;let allowed=['pending','quoted','approved','in_progress','review','completed','cancelled','rejected'];if(!allowed.includes(status)){toast('Invalid status.',true);return}let progress=Number(prompt('Progress percent (0–100)',String(o.progress||0)));if(!Number.isFinite(progress)||progress<0||progress>100){toast('Enter progress 0–100.',true);return}let note=prompt('Client-visible update',o.adminNote||'');await updateDoc(doc(db,'orders',id),{status,progress,adminNote:String(note||'').slice(0,2000),updatedAt:stamp()});await notify(o.clientUid,'Project updated',`${o.title}: ${status.replaceAll('_',' ')}.`);await audit('project.updated','orders',id,`Status ${status}, progress ${progress}%`)}
else if(v==='quote-status'){let status=prompt('New quote status: sent, accepted, declined, expired','sent');if(!['sent','accepted','declined','expired'].includes(status))return;let q=state.quotes.find(x=>x.id===id);await updateDoc(doc(db,'quotes',id),{status,updatedAt:stamp()});if(q?.clientUid)await notify(q.clientUid,'Quotation updated',`Quotation status: ${status}.`);await audit('quote.status_changed','quotes',id,status)}
else if(v==='record-payment'){let i=state.invoices.find(x=>x.id===id);if(!i)return;let amount=Number(prompt('Total verified amount paid so far',String(i.amountPaid||0)));if(!Number.isFinite(amount)||amount<0||amount>Number(i.total||0)){toast('Enter a valid amount up to invoice total.',true);return}let status=amount>=Number(i.total)?'paid':amount>0?'partial':'unpaid';await updateDoc(doc(db,'invoices',id),{amountPaid:amount,status,updatedAt:stamp(),verifiedBy:state.user.uid});await notify(i.clientUid,'Payment record updated',`Invoice ${i.number||id} payment status: ${status}.`);await audit('invoice.payment_recorded','invoices',id,`Recorded paid ${amount} ${i.currency||'PKR'}`)}
else if(v==='booking-status'){let status=prompt('Status: requested, confirmed, completed, cancelled','confirmed');if(!['requested','confirmed','completed','cancelled'].includes(status))return;let b=state.bookings.find(x=>x.id===id);await updateDoc(doc(db,'bookings',id),{status,updatedAt:stamp()});await notify(b.clientUid,'Booking updated',`Your consultation booking is ${status}.`);await audit('booking.updated','bookings',id,status)}
else if(v==='reply-ticket'){let reply=prompt('Reply to client');if(reply===null)return;let t=state.tickets.find(x=>x.id===id);await updateDoc(doc(db,'supportTickets',id),{adminReply:reply.slice(0,3000),status:'answered',updatedAt:stamp()});await notify(t.clientUid,'Support replied','Brightora replied to your support request.');await audit('support.replied','supportTickets',id,'Admin reply sent')}
else if(v==='close-ticket'){await updateDoc(doc(db,'supportTickets',id),{status:'closed',updatedAt:stamp()});await audit('support.closed','supportTickets',id,'Ticket closed')}
else if(v==='toggle-content'){let c=state.content.find(x=>x.id===id);await updateDoc(doc(db,'siteContent',id),{published:!c.published,updatedAt:stamp()});await audit('cms.published','siteContent',id,String(!c.published))}
else if(v==='delete-content'){if(!confirm('Delete this content permanently?'))return;await deleteDoc(doc(db,'siteContent',id));await audit('cms.deleted','siteContent',id,'Deleted')}
else if(v==='toggle-service'){let s=state.services.find(x=>x.id===id);await updateDoc(doc(db,'services',id),{active:!s.active,updatedAt:stamp()});await audit('service.visibility_changed','services',id,String(!s.active))}
else if(v==='delete-service'){if(!confirm('Delete this service?'))return;await deleteDoc(doc(db,'services',id));await audit('service.deleted','services',id,'Deleted')}
else if(v==='disable-staff'){let s=state.staff.find(x=>x.id===id);if(s)await updateDoc(doc(db,'staff',id),{active:false,updatedAt:stamp()});await audit('staff.disabled','staff',id,'Disabled staff record')}
await renderPortal();toast('Update saved.')}
async function handlePortalSubmit(e){let f=e.target;if(!f.id)return;e.preventDefault();let fd=new FormData(f);try{if(f.id==='profileForm'){let p={name:String(fd.get('name')).trim(),phone:String(fd.get('phone')||'').trim(),city:String(fd.get('city')||'').trim(),country:String(fd.get('country')||'').trim(),notes:String(fd.get('notes')||'').trim(),updatedAt:stamp()};await updateDoc(doc(db,'users',state.user.uid),p);state.profile={...state.profile,...p};if(state.user.displayName!==p.name)await updateProfile(state.user,{displayName:p.name});toast('Profile updated.');await renderPortal()}
else if(f.id==='supportForm'){let s=String(fd.get('subject')).trim(),m=String(fd.get('message')).trim();await addDoc(collection(db,'supportTickets'),{clientUid:state.user.uid,clientEmail:state.user.email||'',subject:s,message:m,orderId:String(fd.get('orderId')||''),status:'open',adminReply:'',createdAt:stamp(),updatedAt:stamp()});await notifyOwner('New support request',`${state.user.email}: ${s}`);await audit('support.created','supportTickets','new',s);toast('Support request sent.');await renderPortal()}
else if(f.id==='bookingForm'){let d=String(fd.get('date')),time=String(fd.get('time'));if(new Date(`${d}T${time}`)<new Date()){throw Error('Choose a future date and time.')}let r=await addDoc(collection(db,'bookings'),{clientUid:state.user.uid,clientEmail:state.user.email||'',date:d,time,timezone:String(fd.get('timezone')),topic:String(fd.get('topic')).trim(),status:'requested',createdAt:stamp(),updatedAt:stamp()});await notifyOwner('Consultation requested',`${state.user.email} requested ${d} ${time}.`);await audit('booking.requested','bookings',r.id,d+' '+time);toast('Booking request submitted.');state.panel='bookings';await renderPortal()}
else if(f.id==='cmsForm'){let p={type:String(fd.get('type')),title:String(fd.get('title')).trim(),category:String(fd.get('category')||'').trim(),url:safeUrl(String(fd.get('url')||'')),body:String(fd.get('body')||'').trim(),published:fd.get('published')==='on',createdAt:stamp(),updatedAt:stamp(),createdBy:state.user.uid};await addDoc(collection(db,'siteContent'),p);await audit('cms.created','siteContent','new',p.title);await loadPublic();toast('Content saved.');await renderPortal()}
else if(f.id==='serviceForm'){let p={name:String(fd.get('name')).trim(),category:String(fd.get('category')).trim(),description:String(fd.get('description')).trim(),startingPrice:Number(fd.get('startingPrice')||0),currency:String(fd.get('currency')||'PKR'),active:fd.get('active')==='on',createdAt:stamp(),updatedAt:stamp()};await addDoc(collection(db,'services'),p);await audit('service.created','services','new',p.name);await loadPublic();toast('Service saved.');await renderPortal()}
else if(f.id==='settingsForm'){let p={brandName:String(fd.get('brandName')).trim(),supportEmail:String(fd.get('supportEmail')||'').trim(),currency:String(fd.get('currency')||'PKR'),bookingDuration:Number(fd.get('bookingDuration')||30),paymentInstructions:String(fd.get('paymentInstructions')||'').trim(),maintenanceMode:fd.get('maintenanceMode')==='on',updatedAt:stamp()};await setDoc(doc(db,'settings','public'),p,{merge:true});state.settings={...state.settings,...p};await audit('settings.updated','settings','public','Public settings changed');toast('Settings saved.');await renderPortal()}
else if(f.id==='staffForm'){let uid=String(fd.get('uid')).trim(),name=String(fd.get('name')).trim(),role=String(fd.get('role'));let ref=await addDoc(collection(db,'staff'),{uid,name,role,active:true,createdAt:stamp(),updatedAt:stamp(),createdBy:state.user.uid});toast('Staff record created. Now add this UID to settings/ownerAccess.staffUids and staffRoles in Firestore.');await audit('staff.created','staff',ref.id,role);await renderPortal()}}
catch(e){let target=f.querySelector('.form-message');if(target)msg(target.id,errText(e),true);else toast(errText(e),true)}}
function wire(){ $('mobileMenu').addEventListener('click',()=>$('mainNav').classList.toggle('open'));$('loginNav').addEventListener('click',()=>authModal('login'));$('startNav').addEventListener('click',()=>openProject());$('dashboardNav').addEventListener('click',async()=>{state.panel='overview';await renderPortal()});$('accountNav').addEventListener('click',async()=>{state.panel='profile';await renderPortal()});$('newProjectButton').addEventListener('click',()=>openProject());$('backHome').addEventListener('click',()=>{$('portal').classList.add('hidden');$('publicSite').classList.remove('hidden');document.querySelector('.footer').classList.remove('hidden')});$('logoutButton').addEventListener('click',async()=>{await signOut(auth);state.panel='overview';toast('Signed out.')});$('tabLogin').addEventListener('click',()=>setAuthMode('login'));$('tabSignup').addEventListener('click',()=>setAuthMode('signup'));$('authForm').addEventListener('submit',handleAuth);$('googleLogin').addEventListener('click',async()=>{try{await signInWithPopup(auth,googleProvider);closeModal('authModal')}catch(e){msg('authMessage',errText(e),true)}});$('resetPassword').addEventListener('click',async()=>{try{await sendPasswordResetEmail(auth,$('authEmail').value.trim());msg('authMessage','Password reset email sent.')}catch(e){msg('authMessage',errText(e),true)}});$('projectForm').addEventListener('submit',submitProject);$('contactForm').addEventListener('submit',handleContact);document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.close)));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));document.addEventListener('click',async e=>{let svc=e.target.closest('[data-service]');if(svc){openProject(svc.dataset.service);return}let aa=e.target.closest('[data-auth-action]');if(aa){openProject();return}let act=e.target.closest('[data-action]');if(act){try{await action(act.dataset.action)}catch(err){toast(errText(err),true)}return}let pn=e.target.closest('[data-panel]');if(pn){state.panel=pn.dataset.panel;await renderPortal()}});$('portalContent').addEventListener('submit',handlePortalSubmit)}
async function init(){ $('year').textContent=new Date().getFullYear();wire();await loadPublic();if(!firebaseConfigured)toast('Setup required: add the Firebase Web API key and App ID in js/firebase.js.',true);if(firebaseConfigured){try{await authPersistence;onAuthStateChanged(auth,async user=>{state.user=user;signedUI(user);if(user){try{await ensureProfile(user);signedUI(user);state.panel='overview';await renderPortal()}catch(e){toast(errText(e),true)}}else{state.profile=null;state.isOwner=false;state.isStaff=false;$('portal').classList.add('hidden');$('publicSite').classList.remove('hidden');document.querySelector('.footer').classList.remove('hidden')}})}catch(e){toast(errText(e),true)}}}
init();
